<?php session_start();if(!isset($_SESSION["employee_id"])){header("Location: login.php");exit;}include "db.php";$s=$conn->prepare("SELECT * FROM leave_applications WHERE employee_id=? ORDER BY id DESC");$s->bind_param("i",$_SESSION["employee_id"]);$s->execute();$rows=$s->get_result();?>
<!doctype html><html><head><title>My Leaves</title><link rel=stylesheet href=style.css></head><body><header><nav><b>🏢 Leave Management</b><span><a href=dashboard.php>Dashboard</a><a href=apply_leave.php>Apply</a><a href=logout.php>Logout</a></span></nav></header><main class=container><h2>My Leave Applications</h2><?php if(isset($_GET["applied"]))echo"<p class=success>Application submitted.</p>";?><table><tr><th>ID</th><th>Type</th><th>From</th><th>To</th><th>Days</th><th>Reason</th><th>Status</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td>#<?php echo$r["id"];?></td><td><?php echo htmlspecialchars($r["leave_type"]);?></td><td><?php echo$r["from_date"];?></td><td><?php echo$r["to_date"];?></td><td><?php echo$r["days"];?></td><td><?php echo htmlspecialchars($r["reason"]);?></td><td><?php echo$r["status"];?></td></tr><?php endwhile;?></table></main></body></html>